  const identityKeys = ['id', 'manufacturer', 'model', 'fuel', 'gcNumber', 'productNumber', 'generation'];
  const same = (a, b) => JSON.stringify(a) === JSON.stringify(b);
  function render(parent, selected, guide, task) {
    const bundle = bundles.find(x => x.id === selected?.id);
    if (!bundle || !identityKeys.every(k => (selected[k] ?? null) === (bundle.identity[k] ?? null))) return 0;
    if (guide?.model !== selected.model || guide?.fuel !== selected.fuel) return 0;
    const allowed = bundle.taskBindings[task?.id];
    if (!allowed || !same(task.illustrationPages, allowed)) return 0;
    const refs = (task.steps || []).flatMap(s => s.refs || []);
    let count = 0;
    for (const page of allowed) {
      const pin = bundle.illustrations.find(x => x.page === page);
      if (!pin || !/^[a-f0-9]{64}$/.test(pin.sha256) || !/^[a-f0-9]{64}$/.test(pin.sourceSHA256)) continue;
      if (!/^manual-pages\/[a-z0-9-]+\/page-[0-9]+\.png$/.test(pin.asset)) continue;
      const doc = (guide.documents || []).find(d => d.id === pin.documentId);
      const expectedDoc = bundle.documents.find(d => d.id === pin.documentId);
      if (!doc || !expectedDoc || doc.sha256 !== pin.sourceSHA256 || !same(doc, expectedDoc)) continue;
      if (!refs.some(r => r.documentId === pin.documentId && r.page === page)) continue;
      const image = (guide.illustrations || []).find(x => x.page === page && x.documentId === pin.documentId);
      if (!same(image, pin)) continue;
      if (Array.from(parent.querySelectorAll('[data-reviewed-source-page]')).some(x => x.dataset.reviewedSourcePage === pin.asset)) continue;
      const figure = document.createElement('figure');
      figure.className = 'original-service-figure';
      figure.dataset.reviewedSourcePage = pin.asset;
      if (pin.caption) {
        const scope = document.createElement('figcaption');
        scope.className = 'workflow-safety';
        scope.textContent = pin.caption;
        figure.append(scope);
      }
      const link = document.createElement('a');
      link.href = './' + pin.asset;
      link.target = '_blank'; link.rel = 'noopener noreferrer';
      const picture = document.createElement('img');
      picture.src = './' + pin.asset;
      picture.alt = doc.reference + ', original page ' + page + ': ' + task.title;
      picture.loading = 'lazy'; picture.decoding = 'async';
      picture.style.maxWidth = '100%'; picture.style.height = 'auto';
      const caption = document.createElement('span');
      caption.textContent = 'Open full-size original page ' + page + ' ↗';
      link.append(picture, caption); figure.append(link); parent.append(figure); count++;
    }
    return count;
  }
  Object.defineProperty(globalThis, 'StagReviewedServicePages', {value: Object.freeze({render}), configurable: false});
